def handle_rest_request(method: str, path: str, body: dict, database: dict) -> tuple:
    method = method.upper()
    parts = [p for p in path.strip('/').split('/') if p]

    if not parts or parts[0] != 'orders':
        return (404, {'error': 'Resource Not Found'})

    # Collection endpoint: /orders
    if len(parts) == 1:
        if method == 'GET':
            return (200, list(database.values()))
        elif method == 'POST':
            if not body or 'item' not in body or 'amount' not in body:
                return (400, {'error': 'Bad Request: Missing required fields'})
            new_id = len(database) + 1
            while new_id in database:
                new_id += 1
            new_order = {'id': new_id, 'item': body['item'], 'amount': body['amount']}
            database[new_id] = new_order
            return (201, new_order)
        else:
            return (405, {'error': 'Method Not Allowed'})

    # Item endpoint: /orders/<id>
    elif len(parts) == 2:
        try:
            item_id = int(parts[1])
        except ValueError:
            return (400, {'error': 'Invalid ID format'})

        if method == 'GET':
            if item_id in database:
                return (200, database[item_id])
            return (404, {'error': 'Not Found'})
        elif method == 'DELETE':
            if item_id in database:
                del database[item_id]
                return (204, None)
            return (404, {'error': 'Not Found'})
        else:
            return (405, {'error': 'Method Not Allowed'})

    return (404, {'error': 'Not Found'})
